                <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">
                  Center Address
                </label>
                <input
                  type="text"
                  defaultValue="Block B, Sector 14, Main Market, Delhi NCR - 110001"
                  className="w-full text-sm border border-slate-200 rounded-xl px-4 py-2.5 bg-slate-50 focus:bg-white"
                />
              </div>

              <div className="pt-4 border-t border-slate-100 flex justify-end">
                <button
                  type="submit"
                  className="bg-[#304b62] hover:bg-[#253b4e] text-white font-bold px-6 py-2.5 rounded-xl text-xs shadow-md transition-all"
                >
                  Save Institute Settings
                </button>
              </div>
            </form>
          </div>
        )}
      </div>

      {/* Create Batch Modal */}
      <CreateBatchModal
        isOpen={createBatchOpen}
        onClose={() => setCreateBatchOpen(false)}
        teachers={teachers}
        onBatchCreated={fetchAllAdminData}
      />

      {/* Add Teacher Modal */}
      <AddTeacherModal
        isOpen={addTeacherOpen}
        onClose={() => setAddTeacherOpen(false)}
        onTeacherAdded={fetchAllAdminData}
      />

      {/* View Batch Students Modal */}
      {selectedBatchStudentsModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs animate-fadeIn">
          <div className="bg-white rounded-3xl max-w-lg w-full p-6 md:p-8 shadow-2xl border border-slate-200 space-y-4 max-h-[85vh] overflow-y-auto">
            <div className="flex items-center justify-between pb-3 border-b border-slate-100">
              <div>
                <span className="text-xs font-bold text-[#d49539] uppercase tracking-wider">
                  Class {selectedBatchStudentsModal.class_number} Roster
                </span>
                <h3 className="text-xl font-black text-[#304b62]">{selectedBatchStudentsModal.name}</h3>
              </div>
              <button
                onClick={() => setSelectedBatchStudentsModal(null)}
                className="text-slate-400 hover:text-slate-600 text-xs font-bold px-2 py-1 bg-slate-100 rounded-lg"
              >
                Close
              </button>
            </div>

            <div className="space-y-2">
              <div className="text-xs font-bold text-slate-500 uppercase tracking-wider">
                Enrolled Students ({selectedBatchStudentsModal.student_ids?.length || 0}):
              </div>
              <div className="divide-y divide-slate-100 border border-slate-100 rounded-xl overflow-hidden">
                {selectedBatchStudentsModal.student_ids?.map((s, idx) => (
                  <div key={idx} className="p-3 bg-slate-50/50 flex items-center justify-between text-xs">
                    <span className="font-bold text-[#304b62]">{s.name || `Student ${idx + 1}`}</span>
                    <span className="text-slate-400 font-mono">{s.roll_no || `SM-C${selectedBatchStudentsModal.class_number}-${idx + 1}`}</span>
                  </div>
                ))}
                {(!selectedBatchStudentsModal.student_ids || selectedBatchStudentsModal.student_ids.length === 0) && (
                  <div className="p-6 text-center text-slate-400 text-xs">No students enrolled yet.</div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Admin;
